#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, k, a, b;
    cin >> n >> k >> a >> b;

    if (n <= 1) {
        cout << 0 << '\n';
        return 0;
    }

    if (k <= 1) {
        cout << (n - 1) * a << '\n';
        return 0;
    }

    int64 cost = 0;

    while (n > 1) {
        if (n < k) {
            cost += (n - 1) * a;
            break;
        }

        int64 remainder = n % k;
        cost += remainder * a;
        n -= remainder;

        if (n == 1) break;

        cost += min(b, (n - n / k) * a);
        n /= k;
    }

    cout << cost << '\n';
    return 0;
}

