#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

int64 n, k, a, b;

int64 solve(int64 x) {
    if (x <= 1) return 0;
    if (k <= 1) return (x - 1) * a;

    int64 result = (x - 1) * a;
    int64 remainder = x % k;
    int64 divisible = x - remainder;

    if (divisible >= k) {
        result = min(result, remainder * a + b + solve(divisible / k));
    }

    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n >> k >> a >> b;
    cout << solve(n) << '\n';

    return 0;
}

