#include <bits/stdc++.h>
using namespace std;

using i128 = __int128_t;
using int64 = long long;

void print128(i128 x) {
    if (x == 0) {
        cout << '0';
        return;
    }
    if (x < 0) {
        cout << '-';
        x = -x;
    }
    string s;
    while (x > 0) {
        s.push_back(char('0' + x % 10));
        x /= 10;
    }
    reverse(s.begin(), s.end());
    cout << s;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 n, k, a, b;
    cin >> n >> k >> a >> b;

    if (n <= 1) {
        cout << 0 << '\n';
        return 0;
    }

    if (k <= 1) {
        print128((i128)(n - 1) * a);
        cout << '\n';
        return 0;
    }

    vector<int64> states;
    for (int64 x = n; x >= k; x /= k)
        states.push_back(x);

    i128 result = (i128)(states.empty() ? n - 1 : states.back() / k - 1) * a;

    for (auto it = states.rbegin(); it != states.rend(); ++it) {
        int64 x = *it;
        i128 decrementOnly = (i128)(x - 1) * a;
        i128 divide = (i128)(x % k) * a + b + result;
        result = min(decrementOnly, divide);
    }

    print128(result);
    cout << '\n';
    return 0;
}

